  1148	            SELECT linked_id
  1149	            FROM unnest(e.entity_ids) AS linked_id
  1150	            WHERE NOT (linked_id = ANY(${entityTreeIdsLiteral}::bigint[]))
  1151	          )
  1152	          WHERE e.id IN (
  1153	            SELECT id FROM events
  1154	            WHERE entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1155	            LIMIT ${EVENT_DETACH_BATCH}
  1156	          )
  1157	          RETURNING e.id
  1158	        `;
  1159	        if (detached.length < EVENT_DETACH_BATCH) break;
  1160	      }
