     1	/**
     2	 * Shared AJV construction + error formatting.
     3	 *
     4	 * Both the server (schema-validation, event-kind-validation, operations input
     5	 * validation) and the CLI (`lobu apply` connector-config validation) validate
     6	 * runtime JSON Schemas with AJV. They kept separate, drifting singletons — the
     7	 * server's hardened against a CWE-400 error-amplification DoS (`allErrors:false`,
     8	 * see below), the CLI's not. This is the single source for the setup.
     9	 *
    10	 * `createAjv` takes the options rather than hard-coding one config: the server
    11	 * and CLI make genuinely different, intentional choices (the server coerces
    12	 * types and fails fast on untrusted remote input; the CLI reports every error
    13	 * for a friendlier `lobu apply` on the operator's own local config). Sharing the
    14	 * factory + formatter removes the duplicated dependency wiring without forcing
    15	 * either caller to inherit the other's trade-offs.
    16	 *
    17	 * On `allErrors`: these instances validate UNTRUSTED metadata from agent tool
    18	 * calls and the public REST surface. With `allErrors: true` an adversary can
    19	 * craft an object that forces AJV to allocate an unbounded number of error
    20	 * objects (CWE-400 / CodeQL `js/resource-exhaustion-from-deep-object-traversal`).
    21	 * The server therefore passes `allErrors: false` (fail-fast) and additionally
    22	 * bounds inputs before validating. Callers over trusted/local input (the CLI)
    23	 * may opt into `allErrors: true` for fuller diagnostics.
    24	 */
    25	
    26	import Ajv, { type ErrorObject, type Options } from "ajv";
    27	import addFormats from "ajv-formats";
    28	
    29	/**
    30	 * Build a configured AJV instance with the standard formats registered. Pass
    31	 * the options that fit the call site's threat model (see module doc); nothing
    32	 * is defaulted for you so the choice stays explicit at each construction site.
    33	 */
    34	export function createAjv(options: Options): Ajv {
    35	  const ajv = new Ajv(options);
    36	  addFormats(ajv);
    37	  return ajv;
    38	}
    39	
    40	/** Render one AJV error into a human-readable, field-prefixed message. */
    41	export function formatAjvError(error: ErrorObject): string {
    42	  const field = error.instancePath
    43	    ? error.instancePath.replace(/^\//, "")
    44	    : "root";
    45	  switch (error.keyword) {
    46	    case "type":
    47	      return `${field}: must be ${error.params.type}`;
    48	    case "required":
    49	      return `missing required field: ${error.params.missingProperty}`;
    50	    case "format":
    51	      return `${field}: must be a valid ${error.params.format}`;
    52	    case "minimum":
    53	      return `${field}: must be >= ${error.params.limit}`;
    54	    case "maximum":
    55	      return `${field}: must be <= ${error.params.limit}`;
    56	    case "minLength":
    57	      return `${field}: must be at least ${error.params.limit} characters`;
    58	    case "maxLength":
    59	      return `${field}: must be at most ${error.params.limit} characters`;
    60	    case "pattern":
    61	      return `${field}: must match pattern ${error.params.pattern}`;
    62	    case "enum":
    63	      return `${field}: must be one of: ${(error.params.allowedValues as string[]).join(", ")}`;
    64	    case "additionalProperties":
    65	      return `${field}: unknown property '${error.params.additionalProperty}'`;
    66	    default:
    67	      return error.message ?? `${field}: validation failed`;
    68	  }
    69	}
