   1	/**
   2	 * Schema Validation Utility
   3	 *
   4	 * Validates entity metadata against JSON Schema (Draft 7) stored in entity_types table.
   5	 * Uses ajv for validation with format support (uri, date, email, etc.).
   6	 */
   7	
   8	import { getDb } from '../db/client';
   9	import type { ToolContext } from '../tools/registry';
  10	import { formatAjvError, getAjv } from './ajv-singleton';
  11	import { exceedsValidationLimits, isEmptyObject } from './metadata-limits';
  12	
  13	// ============================================
  14	// Types
  15	// ============================================
  16	
  17	interface ValidationError {
  18	  path: string;
  19	  message: string;
  20	}
  21	
  22	interface ValidationResult {
  23	  valid: boolean;
  24	  errors?: ValidationError[];
  25	}
  26	
  27	/**
  28	 * Fetch the metadata schema for an entity type from the database.
  29	 * Returns null if no schema is defined (allowing any metadata).
  30	 *
  31	 * Cross-org tolerance: an entity created in the caller's org may carry a
  32	 * type from a public catalog (resolved via the schema search path in
  33	 * `entity-management.ts:249-260`). To validate that entity's metadata we
  34	 * must load the catalog's schema, not the caller's. Same lookup shape as
  35	 * the create-side resolver: tenant first, then public catalogs.
  36	 */
  37	async function getEntityTypeSchema(
  38	  entityType: string,
  39	  ctx: ToolContext
  40	): Promise<Record<string, unknown> | null> {
  41	  const sql = getDb();
  42	
  43	  const rows = await sql.unsafe(
  44	    `SELECT et.metadata_schema
  45	     FROM entity_types et
  46	     LEFT JOIN organization o ON o.id = et.organization_id
  47	     WHERE et.slug = $1
  48	       AND et.deleted_at IS NULL
  49	       AND (et.organization_id = $2 OR o.visibility = 'public')
  50	     ORDER BY (et.organization_id = $2) DESC, et.id ASC
  51	     LIMIT 1`,
  52	    [entityType, ctx.organizationId]
  53	  );
  54	
  55	  return (rows[0]?.metadata_schema as Record<string, unknown>) ?? null;
  56	}
  57	
  58	// ============================================
  59	// Validation Functions
  60	// ============================================
  61	
  62	/**
  63	 * Metadata keys stamped by watcher promotion (`promote-keyed-entities.ts`):
  64	 * platform provenance, not part of any entity-type schema. Excluded from
  65	 * validation so a promoted entity's metadata round-trips — read it, edit a
  66	 * domain field, write it back — under an `additionalProperties: false`
  67	 * schema. `source` is deliberately NOT here: it is a plausible domain field,
  68	 * so it stays subject to the type's schema.
  69	 */
  70	const WATCHER_PROVENANCE_KEYS = [
  71	  'watcher_id',
  72	  'stable_key',
  73	  'window_id',
  74	  'behavior_output',
  75	];
  76	
  77	function withoutWatcherProvenanceKeys(
  78	  metadata: Record<string, unknown>
  79	): Record<string, unknown> {
  80	  if (!WATCHER_PROVENANCE_KEYS.some((key) => key in metadata)) return metadata;
  81	  return Object.fromEntries(
  82	    Object.entries(metadata).filter(([key]) => !WATCHER_PROVENANCE_KEYS.includes(key))
  83	  );
  84	}
  85	
  86	/**
  87	 * Validate entity metadata against the entity type's JSON schema.
  88	 *
  89	 * Returns { valid: true } if:
  90	 * - Metadata passes schema validation
  91	 * - No schema is defined for the entity type (allows any metadata)
  92	 * - Metadata is empty/undefined
  93	 *
  94	 * Returns { valid: false, errors: [...] } if validation fails.
  95	 */
  96	export async function validateEntityMetadata(
  97	  entityType: string,
  98	  metadata: Record<string, unknown> | undefined | null,
  99	  ctx: ToolContext
 100	): Promise<ValidationResult> {
 101	  // No metadata provided - valid (defaults to empty object). Allocation-free
 102	  // emptiness check so a huge untrusted object isn't materialized via
 103	  // Object.keys before the size guard below runs.
 104	  if (!metadata || isEmptyObject(metadata)) {
 105	    return { valid: true };
 106	  }
 107	
 108	  // Bound untrusted input before ANY expensive work. The guard is cheap and
 109	  // short-circuits, so rejecting an oversized/deeply-nested payload here also
 110	  // saves the schema-fetch DB round-trip below — and avoids handing a DoS
 111	  // payload to AJV. Pathologically large metadata is a vector regardless of
 112	  // AJV config, so reject it as a normal validation failure.
 113	  if (exceedsValidationLimits(metadata)) {
 114	    return {
 115	      valid: false,
 116	      errors: [{ path: '/', message: 'metadata exceeds size/nesting limits' }],
 117	    };
 118	  }
 119	
 120	  // Fetch schema for this entity type
 121	  const schema = await getEntityTypeSchema(entityType, ctx);
 122	
 123	  // No schema defined - allow any metadata
 124	  if (!schema || Object.keys(schema).length === 0) {
 125	    return { valid: true };
 126	  }
 127	
 128	  // Validate metadata against schema, ignoring platform provenance keys —
 129	  // they are stamped by watcher promotion outside this validator and would
 130	  // otherwise fail every round-trip under additionalProperties: false.
 131	  const ajv = getAjv();
 132	  const validate = ajv.compile(schema);
 133	  const candidate = withoutWatcherProvenanceKeys(metadata);
 134	  const isValid = validate(candidate);
 135	  if (candidate !== metadata) {
 136	    // The AJV singleton runs with coerceTypes, mutating the validated object
 137	    // in place — callers persist those coercions. When we validated a stripped
 138	    // copy, propagate its top-level coercions back (nested objects are shared
 139	    // by reference, so deeper coercions already landed).
 140	    for (const [key, value] of Object.entries(candidate)) {
 141	      metadata[key] = value;
 142	    }
 143	  }
 144	
 145	  if (isValid) {
 146	    return { valid: true };
 147	  }
 148	
 149	  // Format errors for client consumption
 150	  const errors: ValidationError[] = (validate.errors ?? []).map((err) => ({
 151	    path: err.instancePath || '/',
 152	    message: formatAjvError(err),
 153	  }));
 154	
 155	  return { valid: false, errors };
 156	}
